import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { AddGearForm } from './AddGearForm'
import React from 'react'

// Mock the auth context
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id', email: 'test@example.com' },
    loading: false,
    signIn: vi.fn(),
    signUp: vi.fn(),
    signOut: vi.fn()
  }),
  AuthProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>
}))

// Mock the image upload module
vi.mock('@/lib/imageUpload', () => ({
  uploadGearImage: vi.fn(),
  deleteGearImage: vi.fn()
}))

// Test wrapper for components
const TestWrapper = ({ children }: { children: React.ReactNode }) => {
  return <div>{children}</div>
}

describe('AddGearForm', () => {
  const mockOnAdd = vi.fn()
  const mockOnCancel = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('renders form with required fields', () => {
    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    expect(screen.getByLabelText(/name/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/weight/i)).toBeInTheDocument()
    expect(screen.getByText('Category')).toBeInTheDocument()
    expect(screen.getByLabelText(/model/i)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /add gear/i })).toBeInTheDocument()
  })

  it('shows required field indicators', () => {
    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Check for red asterisks on required fields - there should be multiple
    const asterisks = screen.getAllByText('*')
    expect(asterisks.length).toBeGreaterThanOrEqual(2) // Name and Weight are required

    // Check they have the correct styling
    asterisks.forEach(asterisk => {
      expect(asterisk).toHaveClass('text-red-500', 'font-semibold')
    })
  })

  it('handles form submission with valid data', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Fill in required fields
    await user.type(screen.getByLabelText(/name/i), 'Ultralight Tent')
    await user.type(screen.getByLabelText(/weight/i), '2.5')

    // Submit form
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    await waitFor(() => {
      expect(mockOnAdd).toHaveBeenCalledWith({
        name: 'Ultralight Tent',
        brand: null,
        model: null,
        weight_grams: 71, // 2.5oz = ~71g (smart weight conversion working)
        category: 'Shelter', // Smart category suggestion working for "tent"
        quantity: 1,
        worn: false,
        consumable: false,
        price: null,
        description: null,
        image_url: null,
        notes: null
      })
    })
  })

  it('validates required fields', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Try to submit without filling required fields
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    // Should not call onAdd
    expect(mockOnAdd).not.toHaveBeenCalled()
  })

  it('shows advanced fields when toggled', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Advanced fields should not be visible initially
    expect(screen.queryByLabelText(/price/i)).not.toBeInTheDocument()
    expect(screen.queryByLabelText(/quantity/i)).not.toBeInTheDocument()

    // Click show advanced options
    await user.click(screen.getByText(/show advanced options/i))

    // Advanced fields should now be visible
    expect(screen.getByLabelText(/price/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/quantity/i)).toBeInTheDocument()
    expect(screen.getByText(/notes/i)).toBeInTheDocument()
  })

  it('suggests category based on item name', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Type a name that should trigger category suggestion
    await user.type(screen.getByLabelText(/name/i), 'tent')

    await waitFor(() => {
      // Category should be automatically set to 'Shelter'
      expect(screen.getByText('Shelter')).toBeInTheDocument()
    })
  })

  it('handles weight unit conversion', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Enter weight and select ounces
    await user.type(screen.getByLabelText(/weight/i), '1')

    // Find the weight unit select dropdown button - it shows "oz" by default
    const weightUnitButton = screen.getByRole('button', { name: 'oz' })
    await user.click(weightUnitButton)

    // Select grams from the dropdown, then back to oz to test conversion
    const gOption = screen.getByText('g')
    await user.click(gOption)

    // Click again to reopen and select oz
    await user.click(screen.getByRole('button', { name: 'g' }))
    const ozOption = screen.getByText('oz')
    await user.click(ozOption)

    // Fill in name and submit
    await user.type(screen.getByLabelText(/name/i), 'Test Item')
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    await waitFor(() => {
      expect(mockOnAdd).toHaveBeenCalledWith(
        expect.objectContaining({
          weight_grams: 28 // 1oz ≈ 28g (rounded to integer)
        })
      )
    })
  })

  describe('simplified mode', () => {
    it('hides advanced options in simplified mode', () => {
      render(
        <TestWrapper>
          <AddGearForm onAdd={mockOnAdd} simplified={true} />
        </TestWrapper>
      )

      expect(screen.queryByText(/show advanced options/i)).not.toBeInTheDocument()
    })

    it('shows different button text in simplified mode', () => {
      render(
        <TestWrapper>
          <AddGearForm onAdd={mockOnAdd} simplified={true} />
        </TestWrapper>
      )

      expect(screen.getByRole('button', { name: /add & continue/i })).toBeInTheDocument()
    })
  })
})

