     4→
     5→interface SelectOption {
     6→  value: string
     7→  label: string
     8→}
     9→
    10→interface SelectProps {
    11→  value: string
    12→  onChange: (value: string) => void
    13→  options: SelectOption[]
    14→  placeholder?: string
    15→  disabled?: boolean
    16→  className?: string
    17→}
    18→
    19→export function Select({
    20→  value,
    21→  onChange,
    22→  options,
    23→  placeholder = 'Select...',
    24→  disabled = false,
    25→  className = ''
    26→}: SelectProps) {
    27→  const [isOpen, setIsOpen] = useState(false)
    28→  const selectRef = useRef<HTMLDivElement>(null)
    29→  const listRef = useRef<HTMLDivElement>(null)
    30→
    31→  const selectedOption = options.find(option => option.value === value)
    32→
    33→  // Close dropdown when clicking outside
    34→  useEffect(() => {
    35→    const handleClickOutside = (event: MouseEvent) => {
    36→      if (selectRef.current && !selectRef.current.contains(event.target as Node)) {
    37→        setIsOpen(false)
    38→      }
    39→    }
    40→
    41→    if (isOpen) {
    42→      document.addEventListener('mousedown', handleClickOutside)
    43→      return () => document.removeEventListener('mousedown', handleClickOutside)
    44→    }
    45→  }, [isOpen])
    46→
    47→  // Handle keyboard navigation
    48→  useEffect(() => {
    49→    const handleKeyDown = (event: KeyboardEvent) => {
    50→      if (!isOpen) return
    51→
    52→      switch (event.key) {
    53→        case 'Escape':
    54→          setIsOpen(false)
    55→          break
    56→        case 'ArrowDown': {
    57→          event.preventDefault()
    58→          const currentIndex = options.findIndex(opt => opt.value === value)
    59→          const nextIndex = Math.min(currentIndex + 1, options.length - 1)
    60→          onChange(options[nextIndex].value)
    61→          break
    62→        }
    63→        case 'ArrowUp': {
    64→          event.preventDefault()
    65→          const prevIndex = Math.max(options.findIndex(opt => opt.value === value) - 1, 0)
    66→          onChange(options[prevIndex].value)
    67→          break
    68→        }
    69→        case 'Enter':
    70→          event.preventDefault()
    71→          setIsOpen(false)
    72→          break
    73→      }
    74→    }
    75→
    76→    if (isOpen) {
    77→      document.addEventListener('keydown', handleKeyDown)
