}

import { useState, useRef, useEffect } from 'react'
import { GearCategory, WeightUnit } from '@/types/database'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { captureError } from '@/lib/sentry'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { ChevronDown, ChevronUp, Plus } from 'lucide-react'
import { ImageUploadField } from './ImageUploadField'

interface AddGearFormProps {
  onAdd: (gear: {
    name: string
    weight_grams: number
    category: string
    quantity: number
    worn: boolean
    consumable: boolean
    notes?: string | null
    price?: number | null
    model?: string | null
    description?: string | null
    image_url?: string | null
    brand?: string | null
  }) => void
  onCancel?: () => void
  simplified?: boolean // For trip flow
  standalone?: boolean // Whether to show header and action buttons
}


// Smart category suggestions based on item name
const categorySuggestions: Record<string, GearCategory> = {
  tent: 'Shelter',
  tarp: 'Shelter',
  hammock: 'Shelter',
  footprint: 'Shelter',
  'sleeping bag': 'Sleep System',
  quilt: 'Sleep System',
  pad: 'Sleep System',
  pillow: 'Sleep System',
  stove: 'Cooking',
  pot: 'Cooking',
  spoon: 'Cooking',
  fuel: 'Cooking',
  filter: 'Water',
  bottle: 'Water',
  bladder: 'Water',
  purification: 'Water',
  jacket: 'Clothing',
  pants: 'Clothing',
  shirt: 'Clothing',
  socks: 'Clothing',
  phone: 'Electronics',
  battery: 'Electronics',
  charger: 'Electronics',
  headlamp: 'Electronics',
  'first aid': 'First Aid',
  bandage: 'First Aid',
  medication: 'First Aid',
  map: 'Navigation',
  compass: 'Navigation',
  gps: 'Navigation'
}

export function AddGearForm({ onAdd, onCancel, simplified = false, standalone = true }: AddGearFormProps) {
  // Core fields
  const [name, setName] = useState('')
  const [brand, setBrand] = useState('')
  const [weightValue, setWeightValue] = useState('')
  const [weightUnit, setWeightUnit] = useState<WeightUnit>('oz')
  const [category, setCategory] = useState<GearCategory>('Other')
  const [quantity, setQuantity] = useState(1)

  // Advanced fields
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [worn, setWorn] = useState(false)
  const [consumable, setConsumable] = useState(false)
  const [price, setPrice] = useState('')
  const [model, setModel] = useState('')
  const [description, setDescription] = useState('')
  const [imageUrl, setImageUrl] = useState('')
  const [notes, setNotes] = useState('')

  // UI state
  const [weightError, setWeightError] = useState('')
  const nameInputRef = useRef<HTMLInputElement>(null)

  // Auto-focus on mount (mobile-friendly)
  useEffect(() => {
    if (nameInputRef.current) {
      nameInputRef.current.focus()
    }
  }, [])

  // Smart category suggestion
  useEffect(() => {
    if (name) {
      const lowerName = name.toLowerCase()
      for (const [keyword, suggestedCategory] of Object.entries(categorySuggestions)) {
        if (lowerName.includes(keyword)) {
          setCategory(suggestedCategory)
          break
        }
      }
    }
  }, [name])

  // Parse weight input for smart entry (e.g., "12 oz", "340g")
  const handleWeightBlur = () => {
    const parsed = parseWeightInput(weightValue)
    if (parsed) {
      setWeightValue(parsed.value.toString())
      setWeightUnit(parsed.unit)
      setWeightError('')
    }
  }

  // Calculate weight in grams for display
  const getWeightInGrams = (): number => {
    const value = parseFloat(weightValue)
    if (isNaN(value)) return 0
    return Math.round(convertToGrams(value, weightUnit))
  }

  // Format weight preview in multiple units
  const getWeightPreview = (): string => {
    const grams = getWeightInGrams()
    if (grams === 0) return ''

    const units: WeightUnit[] = ['g', 'oz', 'lb', 'kg']
    const previews = units
      .filter(u => u !== weightUnit)
      .map(u => formatWeightWithUnit(grams, u))

    return `(${previews.join(' / ')})`
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    try {
      // Validate required fields
      if (!name.trim()) {
        nameInputRef.current?.focus()
        return
      }

      const weightNum = parseFloat(weightValue)
      if (isNaN(weightNum) || weightNum <= 0) {
        setWeightError('Please enter a valid weight')
        return
      }

      const weightGrams = getWeightInGrams()

      onAdd({
        name: name.trim(),
        brand: brand.trim() || null,
        weight_grams: weightGrams,
        category,
        quantity,
        worn,
        consumable,
        price: price ? parseFloat(price) : null,
        model: model.trim() || null,
        description: description.trim() || null,
        image_url: imageUrl.trim() || null,
        notes: notes.trim() || null
      })

      // Reset form
      setName('')
      setBrand('')
      setWeightValue('')
      setCategory('Other')
      setQuantity(1)
      setWorn(false)
      setConsumable(false)
      setPrice('')
      setModel('')
      setDescription('')
      setImageUrl('')
      setNotes('')
      setShowAdvanced(false)

      // Re-focus for quick entry
      nameInputRef.current?.focus()

    } catch (error) {
      captureError(error as Error, {
        component: 'AddGearForm',
        action: 'handleSubmit',
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

  return (
    <form 
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      className={standalone ? "bg-white rounded-lg shadow-sm border p-3 sm:p-4 md:p-6" : ""}
      data-add-gear-form
    >
      {standalone && (
        <div className="mb-3 sm:mb-4">
          <h2 className="text-base sm:text-lg font-semibold">Add Gear</h2>
        </div>
      )}

      {/* Core Fields - Always Visible */}
      <div className="space-y-3 sm:space-y-4">
        {/* Row 1: Name and Brand */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="name" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Name <span className="text-red-500 font-semibold">*</span>
            </Label>
            <Input
              ref={nameInputRef}
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Backpack"
              required
              className="flex-1 min-h-[44px] text-base sm:text-sm"
              autoComplete="off"
            />
          </div>
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="brand" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Brand
            </Label>
            <Input
              id="brand"
              type="text"
              value={brand}
              onChange={(e) => setBrand(e.target.value)}
              placeholder="e.g., Gossamer Gear"
              className="flex-1 min-h-[44px] text-base sm:text-sm"
            />
          </div>
        </div>

        {/* Row 2: Model and Category */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="model" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Model
            </Label>
            <Input
              id="model"
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              placeholder="e.g., Mariposa 60L"
              className="flex-1 min-h-[44px] text-base sm:text-sm"
            />
          </div>

          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="category" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Category
            </Label>
            <select
              id="category"
              value={category}
              onChange={(e) => setCategory(e.target.value as GearCategory)}
              className="flex-1 px-3 py-2 border rounded-md bg-white min-h-[44px] text-base sm:text-sm cursor-pointer hover:bg-accent/5 transition-colors appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 fill=%27none%27 viewBox=%270 0 20 20%27%3E%3Cpath stroke=%27%236b7280%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27 stroke-width=%271.5%27 d=%27M6 8l4 4 4-4%27/%3E%3C/svg%3E')] bg-[length:16px_16px] bg-[position:right_12px_center] bg-no-repeat"
            >
              {GEAR_CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Row 3: Weight */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="weight" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Weight <span className="text-red-500 font-semibold">*</span>
            </Label>
            <div className="flex gap-1 flex-1">
              <Input
                id="weight"
                type="number"
                step="0.1"
                value={weightValue}
                onChange={(e) => {
                  setWeightValue(e.target.value)
                  setWeightError('')
                }}
                onBlur={handleWeightBlur}
                placeholder="Weight"
                required
                className={`flex-1 min-h-[44px] text-base sm:text-sm ${weightError ? 'border-red-500' : ''}`}
                inputMode="decimal"
              />
              <select
                value={weightUnit}
                onChange={(e) => setWeightUnit(e.target.value as WeightUnit)}
                className="px-2 py-2 border rounded-md bg-white min-w-[60px] min-h-[44px] text-base sm:text-sm cursor-pointer hover:bg-accent/5 transition-colors appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 fill=%27none%27 viewBox=%270 0 20 20%27%3E%3Cpath stroke=%27%236b7280%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27 stroke-width=%271.5%27 d=%27M6 8l4 4 4-4%27/%3E%3C/svg%3E')] bg-[length:16px_16px] bg-[position:right_6px_center] bg-no-repeat"
              >
                <option value="g">g</option>
                <option value="oz">oz</option>
                <option value="lb">lb</option>
                <option value="kg">kg</option>
              </select>
            </div>
            {weightError && (
              <p className="text-red-500 text-sm mt-1 sm:ml-20">{weightError}</p>
            )}
          </div>
          {/* Weight preview */}
          {getWeightPreview() && (
            <div className="text-sm text-muted-foreground self-center">
              {getWeightPreview()}
            </div>
          )}
        </div>

        {/* Row 4: Options */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <span className="text-sm font-medium sm:w-20 sm:shrink-0">Options</span>
            <div className="flex gap-4 flex-1">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={worn}
                  onChange={(e) => setWorn(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Worn</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={consumable}
                  onChange={(e) => setConsumable(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Consumable</span>
              </label>
            </div>
          </div>
        </div>

        {/* Advanced Fields Toggle */}
        {!simplified && (
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            {showAdvanced ? 'Hide' : 'Show'} advanced options
          </button>
        )}

        {/* Advanced Fields */}
        {showAdvanced && !simplified && (
          <div className="space-y-3 pt-2 border-t">
            {/* Quantity and Price Row */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
              <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                <Label htmlFor="quantity" className="text-sm font-medium sm:w-20 sm:shrink-0">
                  Quantity
                </Label>
                <Input
                  id="quantity"
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                  min="1"
                  className="flex-1 min-h-[44px] text-base sm:text-sm"
                  inputMode="numeric"
                />
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                <Label htmlFor="price" className="text-sm font-medium sm:w-20 sm:shrink-0">
                  Price
                </Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  className="flex-1 min-h-[44px] text-base sm:text-sm"
                  inputMode="decimal"
                />
              </div>
            </div>

            {/* Image Upload */}
            <ImageUploadField
              value={imageUrl}
              onChange={(url) => setImageUrl(url)}
            />

            {/* Description and Notes Row */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
              <div className="flex flex-col sm:flex-row sm:items-start gap-2">
                <Label htmlFor="description" className="text-sm font-medium sm:w-20 sm:shrink-0 sm:mt-2">
                  Info
                </Label>
                <textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="flex-1 px-3 py-2 border rounded-md resize-none min-h-[44px] text-base sm:text-sm"
                  rows={2}
                  placeholder="Brief description"
                />
              </div>

              <div className="flex flex-col sm:flex-row sm:items-start gap-2">
                <Label htmlFor="notes" className="text-sm font-medium sm:w-20 sm:shrink-0 sm:mt-2">
                  Notes
                </Label>
                <textarea
                  id="notes"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="flex-1 px-3 py-2 border rounded-md resize-none min-h-[44px] text-base sm:text-sm"
                  rows={2}
                  placeholder="Additional notes"
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons - only show in standalone mode */}
      {standalone && (
        <div className="flex gap-2 mt-6">
          <Button type="submit" className="flex-1 md:flex-initial">
            <Plus className="h-4 w-4 mr-2" />
            {simplified ? 'Add & Continue' : 'Add Gear'}
          </Button>
          {onCancel && (
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              className="hidden md:inline-flex"
            >
              Cancel
            </Button>
          )}
        </div>
      )}

      {/* Keyboard hint */}
      <p className="text-xs text-gray-500 mt-2 hidden md:block">
        Tip: Press Cmd+Enter to quickly add item
      </p>
    </form>
  )
}

import { useState, useRef, useEffect, forwardRef } from 'react'
import { GearCategory, WeightUnit } from '@/types/database'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { captureError } from '@/lib/sentry'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { ChevronDown, ChevronUp, Plus } from 'lucide-react'
import { ImageUploadField } from './ImageUploadField'

interface AddGearFormProps {
  onAdd: (gear: {
    name: string
    weight_grams: number
    category: string
    quantity: number
    worn: boolean
    consumable: boolean
    notes?: string | null
    price?: number | null
    model?: string | null
    description?: string | null
    image_url?: string | null
    brand?: string | null
  }) => void
  onCancel?: () => void
  simplified?: boolean // For trip flow
  standalone?: boolean // Whether to show header and action buttons
}


// Smart category suggestions based on item name
const categorySuggestions: Record<string, GearCategory> = {
  tent: 'Shelter',
  tarp: 'Shelter',
  hammock: 'Shelter',
  footprint: 'Shelter',
  'sleeping bag': 'Sleep System',
  quilt: 'Sleep System',
  pad: 'Sleep System',
  pillow: 'Sleep System',
  stove: 'Cooking',
  pot: 'Cooking',
  spoon: 'Cooking',
  fuel: 'Cooking',
  filter: 'Water',
  bottle: 'Water',
  bladder: 'Water',
  purification: 'Water',
  jacket: 'Clothing',
  pants: 'Clothing',
  shirt: 'Clothing',
  socks: 'Clothing',
  phone: 'Electronics',
  battery: 'Electronics',
  charger: 'Electronics',
  headlamp: 'Electronics',
  'first aid': 'First Aid',
  bandage: 'First Aid',
  medication: 'First Aid',
  map: 'Navigation',
  compass: 'Navigation',
  gps: 'Navigation'
}

export function AddGearForm({ onAdd, onCancel, simplified = false, standalone = true }: AddGearFormProps) {
  // Core fields
  const [name, setName] = useState('')
  const [brand, setBrand] = useState('')
  const [weightValue, setWeightValue] = useState('')
  const [weightUnit, setWeightUnit] = useState<WeightUnit>('oz')
  const [category, setCategory] = useState<GearCategory>('Other')
  const [quantity, setQuantity] = useState(1)

  // Advanced fields
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [worn, setWorn] = useState(false)
  const [consumable, setConsumable] = useState(false)
  const [price, setPrice] = useState('')
  const [model, setModel] = useState('')
  const [description, setDescription] = useState('')
  const [imageUrl, setImageUrl] = useState('')
  const [notes, setNotes] = useState('')

  // UI state
  const [weightError, setWeightError] = useState('')
  const nameInputRef = useRef<HTMLInputElement>(null)

  // Auto-focus on mount (mobile-friendly)
  useEffect(() => {
    if (nameInputRef.current) {
      nameInputRef.current.focus()
    }
  }, [])

  // Smart category suggestion
  useEffect(() => {
    if (name) {
      const lowerName = name.toLowerCase()
      for (const [keyword, suggestedCategory] of Object.entries(categorySuggestions)) {
        if (lowerName.includes(keyword)) {
          setCategory(suggestedCategory)
          break
        }
      }
    }
  }, [name])

  // Parse weight input for smart entry (e.g., "12 oz", "340g")
  const handleWeightBlur = () => {
    const parsed = parseWeightInput(weightValue)
    if (parsed) {
      setWeightValue(parsed.value.toString())
      setWeightUnit(parsed.unit)
      setWeightError('')
    }
  }

  // Calculate weight in grams for display
  const getWeightInGrams = (): number => {
    const value = parseFloat(weightValue)
    if (isNaN(value)) return 0
    return Math.round(convertToGrams(value, weightUnit))
  }

  // Format weight preview in multiple units
  const getWeightPreview = (): string => {
    const grams = getWeightInGrams()
    if (grams === 0) return ''

    const units: WeightUnit[] = ['g', 'oz', 'lb', 'kg']
    const previews = units
      .filter(u => u !== weightUnit)
      .map(u => formatWeightWithUnit(grams, u))

    return `(${previews.join(' / ')})`
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()

    try {
      // Validate required fields
      if (!name.trim()) {
        nameInputRef.current?.focus()
        return
      }

      const weightNum = parseFloat(weightValue)
      if (isNaN(weightNum) || weightNum <= 0) {
        setWeightError('Please enter a valid weight')
        return
      }

      const weightGrams = getWeightInGrams()

      onAdd({
        name: name.trim(),
        brand: brand.trim() || null,
        weight_grams: weightGrams,
        category,
        quantity,
        worn,
        consumable,
        price: price ? parseFloat(price) : null,
        model: model.trim() || null,
        description: description.trim() || null,
        image_url: imageUrl.trim() || null,
        notes: notes.trim() || null
      })

      // Reset form
      setName('')
      setBrand('')
      setWeightValue('')
      setCategory('Other')
      setQuantity(1)
      setWorn(false)
      setConsumable(false)
      setPrice('')
      setModel('')
      setDescription('')
      setImageUrl('')
      setNotes('')
      setShowAdvanced(false)

      // Re-focus for quick entry
      nameInputRef.current?.focus()

    } catch (error) {
      captureError(error as Error, {
        component: 'AddGearForm',
        action: 'handleSubmit',
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

  return (
    <form 
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      className={standalone ? "bg-white rounded-lg shadow-sm border p-3 sm:p-4 md:p-6" : ""}
      data-add-gear-form
    >
      {standalone && (
        <div className="mb-3 sm:mb-4">
          <h2 className="text-base sm:text-lg font-semibold">Add Gear</h2>
        </div>
      )}

      {/* Core Fields - Always Visible */}
      <div className="space-y-3 sm:space-y-4">
        {/* Row 1: Name and Brand */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="name" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Name <span className="text-red-500 font-semibold">*</span>
            </Label>
            <Input
              ref={nameInputRef}
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Backpack"
              required
              className="flex-1 min-h-[44px] text-base sm:text-sm"
              autoComplete="off"
            />
          </div>
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="brand" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Brand
            </Label>
            <Input
              id="brand"
              type="text"
              value={brand}
              onChange={(e) => setBrand(e.target.value)}
              placeholder="e.g., Gossamer Gear"
              className="flex-1 min-h-[44px] text-base sm:text-sm"
            />
          </div>
        </div>

        {/* Row 2: Model and Category */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="model" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Model
            </Label>
            <Input
              id="model"
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              placeholder="e.g., Mariposa 60L"
              className="flex-1 min-h-[44px] text-base sm:text-sm"
            />
          </div>

          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="category" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Category
            </Label>
            <select
              id="category"
              value={category}
              onChange={(e) => setCategory(e.target.value as GearCategory)}
              className="flex-1 px-3 py-2 border rounded-md bg-white min-h-[44px] text-base sm:text-sm cursor-pointer hover:bg-accent/5 transition-colors appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 fill=%27none%27 viewBox=%270 0 20 20%27%3E%3Cpath stroke=%27%236b7280%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27 stroke-width=%271.5%27 d=%27M6 8l4 4 4-4%27/%3E%3C/svg%3E')] bg-[length:16px_16px] bg-[position:right_12px_center] bg-no-repeat"
            >
              {GEAR_CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>

        {/* Row 3: Weight */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <Label htmlFor="weight" className="text-sm font-medium sm:w-20 sm:shrink-0">
              Weight <span className="text-red-500 font-semibold">*</span>
            </Label>
            <div className="flex gap-1 flex-1">
              <Input
                id="weight"
                type="number"
                step="0.1"
                value={weightValue}
                onChange={(e) => {
                  setWeightValue(e.target.value)
                  setWeightError('')
                }}
                onBlur={handleWeightBlur}
                placeholder="Weight"
                required
                className={`flex-1 min-h-[44px] text-base sm:text-sm ${weightError ? 'border-red-500' : ''}`}
                inputMode="decimal"
              />
              <select
                value={weightUnit}
                onChange={(e) => setWeightUnit(e.target.value as WeightUnit)}
                className="px-2 py-2 border rounded-md bg-white min-w-[60px] min-h-[44px] text-base sm:text-sm cursor-pointer hover:bg-accent/5 transition-colors appearance-none bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 fill=%27none%27 viewBox=%270 0 20 20%27%3E%3Cpath stroke=%27%236b7280%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27 stroke-width=%271.5%27 d=%27M6 8l4 4 4-4%27/%3E%3C/svg%3E')] bg-[length:16px_16px] bg-[position:right_6px_center] bg-no-repeat"
              >
                <option value="g">g</option>
                <option value="oz">oz</option>
                <option value="lb">lb</option>
                <option value="kg">kg</option>
              </select>
            </div>
            {weightError && (
              <p className="text-red-500 text-sm mt-1 sm:ml-20">{weightError}</p>
            )}
          </div>
          {/* Weight preview */}
          {getWeightPreview() && (
            <div className="text-sm text-muted-foreground self-center">
              {getWeightPreview()}
            </div>
          )}
        </div>

        {/* Row 4: Options */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <span className="text-sm font-medium sm:w-20 sm:shrink-0">Options</span>
            <div className="flex gap-4 flex-1">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={worn}
                  onChange={(e) => setWorn(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Worn</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={consumable}
                  onChange={(e) => setConsumable(e.target.checked)}
                  className="rounded"
                />
                <span className="text-sm">Consumable</span>
              </label>
            </div>
          </div>
        </div>

        {/* Advanced Fields Toggle */}
        {!simplified && (
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            {showAdvanced ? 'Hide' : 'Show'} advanced options
          </button>
        )}

        {/* Advanced Fields */}
        {showAdvanced && !simplified && (
          <div className="space-y-3 pt-2 border-t">
            {/* Quantity and Price Row */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
              <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                <Label htmlFor="quantity" className="text-sm font-medium sm:w-20 sm:shrink-0">
                  Quantity
                </Label>
                <Input
                  id="quantity"
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                  min="1"
                  className="flex-1 min-h-[44px] text-base sm:text-sm"
                  inputMode="numeric"
                />
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                <Label htmlFor="price" className="text-sm font-medium sm:w-20 sm:shrink-0">
                  Price
                </Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  className="flex-1 min-h-[44px] text-base sm:text-sm"
                  inputMode="decimal"
                />
              </div>
            </div>

            {/* Image Upload */}
            <ImageUploadField
              value={imageUrl}
              onChange={(url) => setImageUrl(url)}
            />

            {/* Description and Notes Row */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4 lg:gap-6">
              <div className="flex flex-col sm:flex-row sm:items-start gap-2">
                <Label htmlFor="description" className="text-sm font-medium sm:w-20 sm:shrink-0 sm:mt-2">
                  Info
                </Label>
                <textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="flex-1 px-3 py-2 border rounded-md resize-none min-h-[44px] text-base sm:text-sm"
                  rows={2}
                  placeholder="Brief description"
                />
              </div>

              <div className="flex flex-col sm:flex-row sm:items-start gap-2">
                <Label htmlFor="notes" className="text-sm font-medium sm:w-20 sm:shrink-0 sm:mt-2">
                  Notes
                </Label>
                <textarea
                  id="notes"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="flex-1 px-3 py-2 border rounded-md resize-none min-h-[44px] text-base sm:text-sm"
                  rows={2}
                  placeholder="Additional notes"
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons - only show in standalone mode */}
      {standalone && (
        <div className="flex gap-2 mt-6">
          <Button type="submit" className="flex-1 md:flex-initial">
            <Plus className="h-4 w-4 mr-2" />
            {simplified ? 'Add & Continue' : 'Add Gear'}
          </Button>
          {onCancel && (
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              className="hidden md:inline-flex"
            >
              Cancel
            </Button>
          )}
        </div>
      )}

      {/* Keyboard hint */}
      <p className="text-xs text-gray-500 mt-2 hidden md:block">
        Tip: Press Cmd+Enter to quickly add item
      </p>
    </form>
  )
}

