import { useState, useRef, useEffect } from 'react'
import { ChevronDown, Check } from 'lucide-react'
import { Button } from '@/components/ui/button'

interface SelectOption {
  value: string
  label: string
}

interface SelectProps {
  value: string
  onChange: (value: string) => void
  options: SelectOption[]
  placeholder?: string
  disabled?: boolean
  className?: string
}

export function Select({
  value,
  onChange,
  options,
  placeholder = 'Select...',
  disabled = false,
  className = ''
}: SelectProps) {
  const [isOpen, setIsOpen] = useState(false)
  const selectRef = useRef<HTMLDivElement>(null)
  const listRef = useRef<HTMLDivElement>(null)

  const selectedOption = options.find(option => option.value === value)

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (selectRef.current && !selectRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isOpen])

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (!isOpen) return

      switch (event.key) {
        case 'Escape':
          setIsOpen(false)
          break
        case 'ArrowDown': {
          event.preventDefault()
          const currentIndex = options.findIndex(opt => opt.value === value)
          const nextIndex = Math.min(currentIndex + 1, options.length - 1)
          onChange(options[nextIndex].value)
          break
        }
        case 'ArrowUp': {
          event.preventDefault()
          const prevIndex = Math.max(options.findIndex(opt => opt.value === value) - 1, 0)
          onChange(options[prevIndex].value)
          break
        }
        case 'Enter':
          event.preventDefault()
          setIsOpen(false)
          break
      }
    }

    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown)
      return () => document.removeEventListener('keydown', handleKeyDown)
    }
  }, [isOpen, value, onChange, options])

  const handleSelect = (optionValue: string) => {
    onChange(optionValue)
    setIsOpen(false)
  }

  return (
    <div ref={selectRef} className={`relative ${className}`}>
      <Button
        type="button"
        variant="outline"
        onClick={() => !disabled && setIsOpen(!isOpen)}
        disabled={disabled}
        className={`w-full justify-between min-h-[44px] text-left ${
          isOpen ? 'ring-2 ring-primary ring-offset-2' : ''
        }`}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
        id="select-button"
      >
        <span className={selectedOption ? 'text-foreground' : 'text-muted-foreground'}>
          {selectedOption ? selectedOption.label : placeholder}
        </span>
        <ChevronDown 
          className={`h-4 w-4 transition-transform ${isOpen ? 'transform rotate-180' : ''}`} 
        />
      </Button>

      {isOpen && (
        <div
          ref={listRef}
          className="absolute z-50 w-full mt-1 bg-white border border-border rounded-md shadow-lg max-h-60 overflow-auto"
          role="listbox"
          aria-labelledby="select-button"
        >
          {options.map((option, index) => (
            <div
              key={option.value}
              className={`px-3 py-2 cursor-pointer hover:bg-accent focus:bg-accent transition-colors min-h-[44px] flex items-center justify-between ${
                option.value === value ? 'bg-accent/50' : ''
              }`}
              onClick={() => handleSelect(option.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault()
                  handleSelect(option.value)
                }
              }}
              role="option"
              aria-selected={option.value === value}
              tabIndex={0}
            >
              <span>{option.label}</span>
              {option.value === value && (
                <Check className="h-4 w-4 text-primary" />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// Convenience wrapper for common use cases
interface SimpleSelectProps {
  value: string
  onChange: (value: string) => void
  options: string[] | SelectOption[]
  placeholder?: string
  disabled?: boolean
  className?: string
}

export function SimpleSelect({
  value,
  onChange,
  options,
  placeholder,
  disabled,
  className
}: SimpleSelectProps) {
  const selectOptions: SelectOption[] = options.map(option => 
    typeof option === 'string' 
      ? { value: option, label: option }
      : option
  )

  return (
    <Select
      value={value}
      onChange={onChange}
      options={selectOptions}
      placeholder={placeholder}
      disabled={disabled}
      className={className}
    />
  )
}

